{"ok":true,"filePath":"src/agent/index.ts","startLine":1,"endLine":259,"content":"1 | /**
2 |  * Agent - AI 代理
3 |  * 负责编排 LLM 调用和会话管理
4 |  *
5 |  * 注意：此文件是旧版 Agent，建议使用 index-eventbus.ts 以获得 EventBus 集成
6 |  * 要启用 EventBus 功能，请导入 './index-eventbus' 而不是此文件
7 |  */
8 | import EventEmitter from "events";
9 | import { LLMProvider, LLMResponse, Message, ToolCall, ToolSchema, StreamChunk } from "../providers/base";
10 | import { ScopedLogger } from "../util/log";
11 | import { SessionManager } from "../session-v2";
12 | import { ToolRegistry } from "../tool/registry";
13 | 
14 | export interface AgentConfig {
15 |     llmProvider: LLMProvider;
16 |     sessionManager: SessionManager;
17 |     systemPrompt: string;
18 |     /** 默认工具列表（可选），不传则使用 ToolRegistry 中所有工具 */
19 |     defaultTools?: ToolSchema[];
20 |     /** 最大循环次数，0 或 null 表示无限制，默认 1024 */
21 |     maxLoop?: number | null;
22 |     /** 最大 token 数，默认 8000 */
23 |     maxTokens?: number;
24 |     /** 最大输出 token 数，默认 8000 */
25 |     maxOutputTokens?: number;
26 |     /** 工具并发上限，默认 1 */
27 |     toolConcurrency?: number;
28 |     /** 单次工具调用超时（毫秒），默认 300000 (5分钟) */
29 |     toolTimeoutMs?: number;
30 |     /** 连续错误次数上限，默认 2 */
31 |     noProgressLimit?: number;
32 | }
33 | 
34 | export interface AgentRunOptions {
35 |     silent?: boolean;
36 |     tools?: ToolSchema[];
37 |     /** 启用流式响应 */
38 |     stream?: boolean;
39 |     /** 流式回调函数 */
40 |     streamCallback?: (chunk: StreamChunk) => void;
41 | }
42 | 
43 | export interface AgentResponse {
44 |     content: string;
45 |     role: Message['role'];
46 |     type?: Message['type'];
47 | }
48 | 
49 | export default class Agent extends EventEmitter {
50 |     private llmProvider: LLMProvider;
51 |     private logger: ScopedLogger;
52 |     private sessionManager: SessionManager;
53 |     private systemPrompt: string;
54 |     private defaultTools: ToolSchema[] | undefined;
55 |     private maxLoop: number | null | undefined;
56 |     private maxOutputTokens: number;
57 |     private maxTokens: number;
58 |     private noProgressLimit: number;
59 | 
60 |     constructor(config: AgentConfig) {
61 |         super();
62 |         this.llmProvider = config.llmProvider;
63 |         this.sessionManager = config.sessionManager;
64 |         this.systemPrompt = config.systemPrompt;
65 |         this.defaultTools = config.defaultTools;
66 |         this.logger = new ScopedLogger('Agent');
67 |         this.maxLoop = config.maxLoop;
68 | 
69 |         const providerMaxOutput = this.llmProvider.maxOutputTokens;
70 |         const providerMaxTokens = this.llmProvider.maxTokens;
71 |         this.maxOutputTokens = Math.min(config.maxOutputTokens ?? providerMaxOutput, providerMaxOutput);
72 |         this.maxTokens = Math.min(config.maxTokens ?? providerMaxTokens, providerMaxTokens);
73 |         this.noProgressLimit = Math.max(0, config.noProgressLimit ?? 2);
74 | 
75 |         this.sessionManager.maxOutputTokens = this.maxOutputTokens;
76 |         this.sessionManager.maxTokens = this.maxTokens;
77 |     }
78 | 
79 |     /**
80 |      * 执行单个工具调用
81 |      */
82 |     private async executeToolCall(toolCall: ToolCall): Promise<Message> {
83 |         const { name, arguments: args } = toolCall.function;
84 |         if (!name) {
85 |             return {
86 |                 role: 'tool',
87 |                 type: 'text',
88 |                 content: 'Error: Tool name is empty',
89 |                 tool_call_id: toolCall.id,
90 |             };
91 |         }
92 | 
93 |         const result = await ToolRegistry.execute(name, args);
94 | 
95 |         let content: string;
96 |         if (typeof result === 'string') {
97 |             content = result;
98 |         } else {
99 |             content = JSON.stringify(result?.metadata ?? result ?? {});
100 |         }
101 | 
102 |         return {
103 |             role: 'tool',
104 |             type: 'text',
105 |             content,
106 |             tool_call_id: toolCall.id,
107 |         };
108 |     }
109 | 
110 |     /**
111 |      * 处理工具调用，返回是否有工具被调用
112 |      */
113 |     private async handleToolCalls(
114 |         llmResponse: LLMResponse,
115 |         spinner: ReturnType<ScopedLogger['spinner']>
116 |     ): Promise<boolean> {
117 |         if (!llmResponse.tool_calls || llmResponse.tool_calls.length === 0) {
118 |             return false;
119 |         }
120 | 
121 |         const toolResults = await Promise.all(
122 |             llmResponse.tool_calls.map(call => this.executeToolCall(call))
123 |         );
124 | 
125 |         this.sessionManager.addMessage(toolResults);
126 | 
127 |         // Bug修复：提取content字段进行拼接，而非直接join对象数组
128 |         const summaries = toolResults
129 |             .map(r => {
130 |                 const content = r.content ?? '';
131 |                 return content.length > 50 ? content.slice(0, 47) + '...' : content;
132 |             })
133 |             .join(', ');
134 | 
135 |         spinner.succeed(`Tool calls: ${summaries}`);
136 |         return true;
137 |     }
138 | 
139 |     /**
140 |      * 运行 Agent 处理用户查询
141 |      * @param query 用户查询
142 |      * @param options 选项
143 |      * @returns Agent 响应
144 |      */
145 |     async run(
146 |         query: string,
147 |         options?: AgentRunOptions
148 |     ): Promise<AgentResponse | null> {
149 |         const tools = options?.tools ?? this.defaultTools ?? [];
150 |         let consecutiveErrorCount = 0;
151 |         let i = 0;
152 |         const streamEnabled = options?.stream ?? false;
153 |         const streamCallback = options?.streamCallback;
154 | 
155 |         // 添加用户消息
156 |         this.sessionManager.addMessage({
157 |             role: 'user',
158 |             type: 'text',
159 |             content: query,
160 |         });
161 | 
162 |         while (true) {
163 |             i++;
164 | 
165 |             // maxLoop 为 0 或 null 表示无限制
166 |             if (this.maxLoop && this.maxLoop > 0 && i > this.maxLoop) {
167 |                 return {
168 |                     content: `Max loop limit reached (${this.maxLoop})`,
169 |                     role: 'assistant',
170 |                 };
171 |             }
172 | 
173 |             const llmMessages = await this.sessionManager.getMessages();
174 |             const spinner = this.logger.spinner(`Thinking-${i}...`);
175 | 
176 |             try {
177 |                 // 构建包装的流式回调，用于停止 spinner
178 |                 let spinnerStopped = false;
179 |                 const wrappedStreamCallback = streamCallback ? (chunk: StreamChunk) => {
180 |                     if (!spinnerStopped) {
181 |                         spinner.stop();
182 |                         spinnerStopped = true;
183 |                     }
184 |                     // 调用原始回调
185 |                     streamCallback(chunk);
186 |                     // 发送事件
187 |                     this.emit('stream-chunk', chunk);
188 |                 } : undefined;
189 | 
190 |                 const llmResponse = await this.llmProvider.generate(
191 |                     [
192 |                         { role: 'system', content: this.systemPrompt },
193 |                         ...llmMessages,
194 |                     ],
195 |                     {
196 |                         model: process.env.AI_MODEL,
197 |                         tools: tools.length > 0 ? tools : undefined,
198 |                         max_tokens: this.maxOutputTokens,
199 |                         stream: streamEnabled,
200 |                         streamCallback: wrappedStreamCallback,
201 |                     }
202 |                 );
203 | 
204 |                 if (!llmResponse) {
205 |                     throw new Error('LLM response is null');
206 |                 }
207 | 
208 |                 this.sessionManager.addMessage(llmResponse);
209 | 
210 |                 const hasToolCalls = await this.handleToolCalls(llmResponse, spinner);
211 | 
212 |                 if (!hasToolCalls) {
213 |                     // 单次无工具调用即返回，无需继续循环
214 |                     // 正常结束状态：'stop'、'eos'、undefined；其他值可能是异常
215 |                     const validEnd = ['stop', 'eos', undefined].includes(llmResponse.finishReason as string);
216 | 
217 |                     if (!validEnd) {
218 |                         spinner.fail(`Unexpected finishReason: ${llmResponse.finishReason}`);
219 |                         consecutiveErrorCount++;
220 |                         continue;
221 |                     } else {
222 | 
223 |                         spinner.succeed(llmResponse?.content ?? '');
224 | 
225 |                         return {
226 |                             content: llmResponse?.content ?? '',
227 |                             role: 'assistant',
228 |                         }
229 |                     }
230 | 
231 |                 }
232 | 
233 |                 // 工具调用成功，重置连续错误计数
234 |                 consecutiveErrorCount = 0;
235 | 
236 |             } catch (error) {
237 |                 const errorMsg = error instanceof Error ? error.message : String(error);
238 |                 spinner.fail(errorMsg);
239 |                 this.logger.error(`LLM call failed: ${errorMsg}`);
240 | 
241 |                 this.sessionManager.addMessage({
242 |                     role: 'assistant',
243 |                     type: 'text',
244 |                     content: `LLM error: ${errorMsg}`,
245 |                 });
246 | 
247 |                 consecutiveErrorCount++;
248 | 
249 |                 if (consecutiveErrorCount > this.noProgressLimit) {
250 |                     return {
251 |                         content: `Max error limit reached: ${errorMsg}`,
252 |                         role: 'assistant',
253 |                     };
254 |                 }
255 |             }
256 |         }
257 |     }
258 | }
